def get_token_cache_path():
    appdata = os.environ.get("APPDATA") or os.environ.get("LOCALAPPDATA") or os.path.expanduser("~")
    d = os.path.join(appdata, "Seestar_AstroLab")
    os.makedirs(d, exist_ok=True)
    return os.path.join(d, "github_token_cache.txt")


def save_token_to_cache(token):
    if not token or not token.strip():
        return
    try:
        with open(get_token_cache_path(), "w", encoding="utf-8") as f:
            f.write(token.strip())
    except Exception:
        pass


def detect_existing_github_token():
    cache_p = get_token_cache_path()
    if os.path.isfile(cache_p):
        try:
            with open(cache_p, "r", encoding="utf-8") as f:
                t = f.read().strip()
            if t:
                return t
        except Exception:
            pass
    for k in ("GITHUB_TOKEN", "GH_TOKEN"):
        if os.environ.get(k):
            return os.environ[k].strip()
    try:
        res = subprocess.run(["gh", "auth", "token"], capture_output=True, text=True, timeout=5)
        if res.returncode == 0 and res.stdout.strip():
            return res.stdout.strip()
    except Exception:
        pass
    try:
        proc = subprocess.run(
            ["git", "credential", "fill"],
            input="protocol=https\nhost=github.com\n\n",
            capture_output=True, text=True, timeout=5
        )
        if proc.returncode == 0:
            for line in proc.stdout.splitlines():
                if line.startswith("password="):
                    pw = line.split("=", 1)[1].strip()
                    if pw:
                        return pw
    except Exception:
        pass
    return ""


def extract_embedded_payload(target_dir):
    raw_b64 = "".join(EMBEDDED_ARCHIVE_B64.split())
    xz_bytes = base64.b64decode(raw_b64)
    os.makedirs(target_dir, exist_ok=True)
    with lzma.open(io.BytesIO(xz_bytes), "r") as lzf:
        with tarfile.open(fileobj=lzf, mode="r") as tf:
            tf.extractall(target_dir)
    return True


def github_api_request(method, url, token, payload=None):
    headers = {
        "Authorization": f"Bearer {token.strip()}",
        "Accept": "application/vnd.github+json",
        "User-Agent": "Seestar-AstroLab-AAVSO-v1.1.3-beta-Updater",
        "X-GitHub-Api-Version": "2022-11-28",
    }
    data = None
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers["Content-Type"] = "application/json; charset=utf-8"

    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    with urllib.request.urlopen(req, timeout=120) as resp:
        raw = resp.read()
        return json.loads(raw.decode("utf-8")) if raw else {}


def run_github_update(token, work_root):
    save_token_to_cache(token)
    staging_dir = tempfile.mkdtemp(prefix="seestar_v113_stage_")
    extract_embedded_payload(staging_dir)
    try:
        if work_root and os.path.isdir(os.path.join(work_root, "Source_and_Build")):
            extract_embedded_payload(work_root)
    except Exception:
        pass

    print(f"• Подключение к репозиторию {GITHUB_OWNER}/{REPO_NAME} (ветка {BRANCH})...")
    ref_data = github_api_request(
        "GET",
        f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/ref/heads/{BRANCH}",
        token,
    )
    latest_commit_sha = ref_data["object"]["sha"]
    commit_data = github_api_request(
        "GET",
        f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/commits/{latest_commit_sha}",
        token,
    )
    base_tree_sha = commit_data["tree"]["sha"]
    print(f"• Базовый коммит ветки {BRANCH}: {latest_commit_sha[:10]}")

    existing_remote_paths = set()
    try:
        tree_resp = github_api_request(
            "GET",
            f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/trees/{base_tree_sha}?recursive=1",
            token,
        )
        for item in tree_resp.get("tree", []):
            if item.get("path") and item.get("type") == "blob":
                existing_remote_paths.add(item["path"])
    except Exception:
        pass

    tree_items = []
    total_files = len(ALL_PROGRAM_FILES)
    for idx, rel_path in enumerate(ALL_PROGRAM_FILES, 1):
        full_path = os.path.join(staging_dir, rel_path)
        if not os.path.isfile(full_path):
            continue
        with open(full_path, "rb") as f:
            raw_bytes = f.read()
        b64_content = base64.b64encode(raw_bytes).decode("ascii")
        blob_resp = github_api_request(
            "POST",
            f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/blobs",
            token,
            {"content": b64_content, "encoding": "base64"},
        )
        api_path = rel_path.replace("\\", "/")
        tree_items.append({
            "path": api_path,
            "mode": "100644",
            "type": "blob",
            "sha": blob_resp["sha"],
        })
        print(f"  [{idx:02d}/{total_files:02d}] ↑ Выгружен файл: {api_path} ({len(raw_bytes):,} байт)")

    for obs_path in OBSOLETE_FILES_TO_REMOVE:
        if obs_path in existing_remote_paths:
            tree_items.append({
                "path": obs_path,
                "mode": "100644",
                "type": "blob",
                "sha": None,
            })
            print(f"  🗑 Удалён лишний файл: {obs_path}")

    utc_stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
    new_tree_resp = github_api_request(
        "POST",
        f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/trees",
        token,
        {"base_tree": base_tree_sha, "tree": tree_items},
    )
    commit_msg = (
        f"Release v1.1.3 beta: Illustrated 6-slide Guide (Seestar firmware photometry + .csv), "
        f"clean README, Country->City, dropdown Berber (para Ramon) ({utc_stamp})"
    )
    new_commit_resp = github_api_request(
        "POST",
        f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/commits",
        token,
        {
            "message": commit_msg,
            "tree": new_tree_resp["sha"],
            "parents": [latest_commit_sha],
        },
    )
    new_commit_sha = new_commit_resp["sha"]
    github_api_request(
        "PATCH",
        f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/refs/heads/{BRANCH}",
        token,
        {"sha": new_commit_sha, "force": False},
    )
    print(f"\n✅ Ветка main обновлена коммитом: {new_commit_sha[:10]}")

    # Создаём или обновляем тег v1.1.3-beta, чтобы GitHub Actions создал официальный релиз v1.1.3-beta!
    try:
        github_api_request(
            "POST",
            f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/refs",
            token,
            {"ref": f"refs/tags/{RELEASE_TAG}", "sha": new_commit_sha},
        )
        print(f"🏷 Создан тег {RELEASE_TAG} -> GitHub Actions собирает релиз {RELEASE_TAG}!")
    except urllib.error.HTTPError as te:
        if te.code == 422:
            github_api_request(
                "PATCH",
                f"{API_BASE}/repos/{GITHUB_OWNER}/{REPO_NAME}/git/refs/tags/{RELEASE_TAG}",
                token,
                {"sha": new_commit_sha, "force": True},
            )
            print(f"🏷 Обновлён тег {RELEASE_TAG} -> GitHub Actions пересобирает релиз {RELEASE_TAG}!")
        else:
            print(f"⚠ Предупреждение при создании тега {RELEASE_TAG}: {te}")

    print(f"🔗 Репозиторий: https://github.com/{GITHUB_OWNER}/{REPO_NAME}")
    print(f"📦 Релизы: https://github.com/{GITHUB_OWNER}/{REPO_NAME}/releases")


def main():
    if "--dry-run-test" in sys.argv:
        tmp_d = tempfile.mkdtemp(prefix="seestar_v113_dry_")
        extract_embedded_payload(tmp_d)
        for rel_p in ALL_PROGRAM_FILES:
            assert os.path.isfile(os.path.join(tmp_d, rel_p)), f"Missing extracted file: {rel_p}"
        utc_stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
        shutil.rmtree(tmp_d, ignore_errors=True)
        print(f"[DRY RUN OK] Extracted all {len(ALL_PROGRAM_FILES)} v1.1.3 beta files cleanly ({utc_stamp})")
        return

    work_root = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    tok = detect_existing_github_token()
    if tok:
        print("✓ Автоматически обнаружен сохранённый GitHub токен на вашем ПК.")
    else:
        print("Для выгрузки введите ваш GitHub Personal Access Token (ghp_... с правом repo):")
        tok = input("GitHub Token: ").strip()

    if not tok:
        print("✗ Ошибка: токен не введён.")
        sys.exit(1)

    try:
        run_github_update(tok, work_root)
    except urllib.error.HTTPError as he:
        body = ""
        try:
            body = he.read().decode("utf-8", errors="replace")
        except Exception:
            pass
        print(f"\n✗ HTTP Ошибка GitHub API ({he.code} {he.reason}): {body}")
        if he.code == 401:
            try:
                os.remove(get_token_cache_path())
            except Exception:
                pass
            print("Сохранённый токен устарел. Перезапустите скрипт и введите новый токен.")
        sys.exit(1)
    except Exception as e:
        print(f"\n✗ Ошибка: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
